package com.bank.runnerup;

import java.math.BigDecimal;
import java.util.Optional;
import java.util.logging.Logger;

// Finds the second-largest DISTINCT transaction for National Bank of India.
public class RunnerUpService {
    private static final Logger log = Logger.getLogger(RunnerUpService.class.getName());

    // Single pass O(n). Returns empty when there is no distinct runner-up.
    public Optional<BigDecimal> secondLargest(BigDecimal[] amounts) {
        if (amounts == null || amounts.length < 2) {
            log.warning("Need at least two amounts for a runner-up");
            return Optional.empty();
        }
        BigDecimal largest = null;        // gold
        BigDecimal secondLargest = null;  // silver
        for (BigDecimal x : amounts) {
            if (largest == null || x.compareTo(largest) > 0) {
                secondLargest = largest;  // demote old gold to silver FIRST
                largest = x;              // new champion
            } else if (x.compareTo(largest) < 0
                    && (secondLargest == null || x.compareTo(secondLargest) > 0)) {
                secondLargest = x;        // strictly below gold, above silver
            }
        }
        if (secondLargest == null) {
            log.warning("No distinct runner-up (all amounts equal to the max)");
            return Optional.empty();
        }
        final BigDecimal result = secondLargest;
        log.info(() -> "Second-largest (distinct) = Rs." + result);
        return Optional.of(secondLargest);
    }
}
