package com.bank.runnerup;

import java.math.BigDecimal;
import java.util.Optional;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: find Priya's second-highest transaction of the month.
public class RunnerUpDemo {
    private static final Logger log = Logger.getLogger(RunnerUpDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        RunnerUpService service = new RunnerUpService();

        // Priya (CUR3001) monthly amounts; note the duplicate 250000 (rent).
        BigDecimal[] amounts = {
            new BigDecimal("250000"), new BigDecimal("48000"),
            new BigDecimal("250000"), new BigDecimal("120000"),
            new BigDecimal("9000")
        };
        Optional<BigDecimal> runnerUp = service.secondLargest(amounts);
        runnerUp.ifPresentOrElse(
            v -> log.info(() -> "Risk review: second-highest distinct = Rs." + v),
            () -> log.warning("Risk review: no distinct runner-up this month")
        );
    }
}
